10	/**
11	 * De-duplicates the assigned {@code customerCode}. If another owner already holds the
12	 * computed code, appends {@code -<n>} with the smallest {@code n >= 2} that is unique.
13	 * The owner is not yet saved, so its own code is absent from the store.
14	 */
15	public class DeduplicateOwnerCustomerCode {
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        Set<String> taken = new HashSet<>();
19	        for (Owner other : ownerRepository.findAll()) {
20	            taken.add(other.getCustomerCode());
21	        }
22	        String base = owner.getCustomerCode();
23	        String code = base;
24	        for (int n = 2; taken.contains(code); n++) {
25	            code = base + "-" + n;
26	        }
27	        owner.setCustomerCode(code);
28	    }
29	}
