1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives the owner's membership number, formatted {@code <customerCode>-M<YY>} where
7	 * {@code YY} is the last two digits of the registration date's fiscal year (e.g. {@code
8	 * SMI-0007-M26}). Returns {@code null} when either input is absent, so owners without a
9	 * customer code or registration date carry no membership number.
10	 */
11	public final class MembershipNumber {
12	
13	    private MembershipNumber() {
14	    }
15	
16	    public static String of(Owner owner) {
17	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
18	            return null;
19	        }
20	        return String.format("%s-M%02d", owner.getCustomerCode(), FiscalYear.of(owner.getRegistrationDate()) % 100);
21	    }
22	}
