1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Scores an owner's membership. Points start at 0 and add 2 for a present email, 1 when the
9	 * namesake count is 0, 2 for a household of 3 or more and 3 for tenure of at least one
10	 * elapsed fiscal year. The numeric level maps those points as 1 (0-1), 2 (2-3), 3 (4-5) and
11	 * 4 (6 or more).
12	 */
13	public final class MembershipLevel {
14	
15	    private MembershipLevel() {
16	    }
17	
18	    public static int points(Owner owner, int namesakeCount, int householdSize) {
19	        int points = 0;
20	        if (owner.getEmail() != null) {
21	            points += 2;
22	        }
23	        if (namesakeCount == 0) {
24	            points += 1;
25	        }
26	        if (householdSize >= 3) {
27	            points += 2;
28	        }
29	        if (hasTenure(owner)) {
30	            points += 3;
31	        }
32	        return points;
33	    }
34	
35	    public static int level(int points) {
36	        return Math.min(points / 2 + 1, 4);
37	    }
38	
39	    private static boolean hasTenure(Owner owner) {
40	        LocalDate registration = owner.getRegistrationDate();
41	        return registration != null
42	                && FiscalYear.of(LocalDate.now()) - FiscalYear.of(registration) >= 1;
43	    }
44	}
45

1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	
6	/**
7	 * Ceilings an owner's membership level to one above the current maximum {@link
8	 * MembershipLevel} among their existing household members — the other live owners resolving
9	 * to the same {@link HouseholdId}. With no existing household member the owner's own level
10	 * stands, so a household's first member is never capped.
11	 */
12	public final class MembershipCap {
13	
14	    private MembershipCap() {
15	    }
16	
17	    public static int apply(Owner owner, int level, OwnerRepository ownerRepository) {
18	        String householdId = HouseholdId.of(owner);
19	        int ceiling = ownerRepository.findAll().stream()
20	                .filter(other -> !other.isDeleted())
21	                .filter(other -> other.getId() != null && !other.getId().equals(owner.getId()))
22	                .filter(other -> householdId.equals(HouseholdId.of(other)))
23	                .mapToInt(other -> MembershipLevel.level(MembershipLevel.points(other,
24	                        Namesakes.countBefore(other, ownerRepository), Household.size(other, ownerRepository))))
25	                .max()
26	                .orElse(-1);
27	        return ceiling < 0 ? level : Math.min(level, ceiling + 1);
28	    }
29	}
